package org.sleepwell.app;
import android.util.JsonReader;import android.util.JsonWriter;import android.util.JsonToken;import java.io.*;import java.nio.*;import java.nio.charset.*;import java.security.*;import java.util.*;
/** Strict portable definitions only: no alarm identity, pending job, device ID or ownership authority. */
final class NapProfilesDefinitions {
 static final int LIMIT=65536;
 static final class Definition {final String name,fingerprint;final List<NapProfiles.Entry> entries;Definition(String name,List<NapProfiles.Entry> entries){NapProfiles.Profile checked=new NapProfiles.Profile(UUID.randomUUID().toString(),name,0,entries);if(!checked.name.equals(name))throw new IllegalArgumentException("Profile names must not contain controls or surrounding whitespace.");for(int n=0;n<name.length();n++){char c=name.charAt(n);if(Character.isHighSurrogate(c)){if(++n>=name.length()||!Character.isLowSurrogate(name.charAt(n)))throw new IllegalArgumentException("Invalid profile name text.");}else if(Character.isLowSurrogate(c))throw new IllegalArgumentException("Invalid profile name text.");}this.name=name;this.entries=checked.entries;fingerprint=hash(canonical(this));}}
 static final class Plan {final List<Definition> incoming,additions;final List<String> conflicts;final int duplicates,current;final String snapshot;Plan(List<Definition> incoming,List<NapProfiles.Profile> existing){this.incoming=List.copyOf(incoming);current=existing.size();snapshot=snapshot(existing);List<Definition> add=new ArrayList<>();List<String> conflict=new ArrayList<>();Set<String> fingerprints=new HashSet<>(),names=new HashSet<>();for(NapProfiles.Profile p:existing){Definition d=new Definition(p.name,p.entries);fingerprints.add(d.fingerprint);names.add(p.name.toLowerCase(Locale.ROOT));}int duplicate=0;for(Definition d:incoming){if(!fingerprints.add(d.fingerprint)){duplicate++;continue;}if(!names.add(d.name.toLowerCase(Locale.ROOT))){conflict.add(d.name);continue;}add.add(d);}additions=List.copyOf(add);conflicts=List.copyOf(conflict);duplicates=duplicate;}boolean fits(){return current+additions.size()<=20;}}
 static List<Definition> decode(byte[] bytes)throws IOException{if(bytes.length==0||bytes.length>LIMIT)throw new IOException("Choose a profile document no larger than 64 KiB.");String text;try{text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();}catch(CharacterCodingException invalid){throw new IOException("Profile documents must use valid UTF-8.",invalid);}try(JsonReader reader=new JsonReader(new StringReader(text))){reader.setLenient(false);reader.beginObject();Set<String> fields=new HashSet<>();String format=null;Integer version=null;List<Definition> definitions=null;while(reader.hasNext()){String key=reader.nextName();if(!fields.add(key))throw new IOException("Duplicate profile document field.");switch(key){case "format"->format=string(reader,40);case "version"->version=integer(reader);case "profiles"->{definitions=new ArrayList<>();reader.beginArray();while(reader.hasNext()){if(definitions.size()>=20)throw new IOException("A document may contain at most 20 profiles.");definitions.add(definition(reader));}reader.endArray();}default->throw new IOException("Unexpected profile document field.");}}reader.endObject();if(reader.peek()!=JsonToken.END_DOCUMENT||fields.size()!=3||!"sleepwell-nap-profiles".equals(format)||version==null||version!=1||definitions==null||definitions.isEmpty())throw new IOException("Choose a version 1 SleepWell nap-profile document with 1–20 definitions.");return List.copyOf(definitions);}catch(IllegalArgumentException|IllegalStateException bad){throw new IOException("This profile document has invalid names, entries or structure.",bad);}}
 private static Definition definition(JsonReader r)throws IOException{r.beginObject();Set<String> keys=new HashSet<>();String name=null;List<NapProfiles.Entry> entries=null;while(r.hasNext()){String key=r.nextName();if(!keys.add(key))throw new IOException("Duplicate profile definition field.");switch(key){case "name"->name=string(r,120);case "entries"->{entries=new ArrayList<>();r.beginArray();while(r.hasNext()){if(entries.size()>=6)throw new IOException("A profile may contain at most 6 entries.");r.beginObject();Set<String> fields=new HashSet<>();Integer minute=null,duration=null;while(r.hasNext()){String part=r.nextName();if(!fields.add(part))throw new IOException("Duplicate profile entry field.");switch(part){case "minute"->minute=integer(r);case "duration"->duration=integer(r);default->throw new IOException("Unexpected profile entry field.");}}r.endObject();if(fields.size()!=2||minute==null||duration==null)throw new IOException("Profile entries need start minute and duration.");entries.add(new NapProfiles.Entry(minute,duration));}r.endArray();}default->throw new IOException("Unexpected profile definition field.");}}r.endObject();if(keys.size()!=2||name==null||entries==null)throw new IOException("Incomplete profile definition.");return new Definition(name,entries);}
 private static int integer(JsonReader reader)throws IOException{if(reader.peek()!=JsonToken.NUMBER)throw new IOException("Profile numbers must be whole numbers.");String raw=reader.nextString();if(!raw.matches("0|[1-9][0-9]{0,8}"))throw new IOException("Profile numbers must be bounded nonnegative integers.");try{return Integer.parseInt(raw);}catch(NumberFormatException bad){throw new IOException("Profile number is outside range.");}}
 private static String string(JsonReader reader,int maximum)throws IOException{if(reader.peek()!=JsonToken.STRING)throw new IOException("Expected profile text.");String value=reader.nextString();if(value.length()>maximum)throw new IOException("Profile text is too long.");return value;}
 static byte[] encode(List<NapProfiles.Profile> profiles)throws IOException{if(profiles.isEmpty()||profiles.size()>20)throw new IOException("Save 1–20 profile definitions before exporting.");StringWriter text=new StringWriter();try(JsonWriter writer=new JsonWriter(text)){writer.setIndent("  ");writer.beginObject().name("format").value("sleepwell-nap-profiles").name("version").value(1).name("profiles").beginArray();for(NapProfiles.Profile profile:profiles)write(writer,new Definition(profile.name,profile.entries));writer.endArray().endObject();}byte[] bytes=text.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>LIMIT)throw new IOException("Profile definitions exceed the 64 KiB export limit.");return bytes;}
 private static void write(JsonWriter writer,Definition d)throws IOException{writer.beginObject().name("name").value(d.name).name("entries").beginArray();for(NapProfiles.Entry e:d.entries)writer.beginObject().name("minute").value(e.minute).name("duration").value(e.duration).endObject();writer.endArray().endObject();}
 private static String canonical(Definition d){try{StringWriter out=new StringWriter();try(JsonWriter writer=new JsonWriter(out)){write(writer,d);}return "nap-profile-definition-v1:"+out;}catch(IOException impossible){throw new IllegalStateException(impossible);}}
 static String snapshot(List<NapProfiles.Profile> profiles){List<NapProfiles.Profile> ordered=new ArrayList<>(profiles);ordered.sort(Comparator.comparing(p->p.id));StringBuilder content=new StringBuilder("nap-profile-snapshot-v1:");for(NapProfiles.Profile p:ordered)content.append(p.id).append(':').append(p.revision).append(':').append(new Definition(p.name,p.entries).fingerprint).append(';');return hash(content.toString());}
 static String hash(String text){try{return Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
 private NapProfilesDefinitions(){}
}
